{
  "examples": [
    {
      "question": "Combien d'éditeurs ont publié des livres écrits par « Camille Dumas » ?",
      "sql": "SELECT COUNT ( DISTINCT T2.publisher_name ) FROM books AS T4 JOIN publishers AS T2 ON T4.publisher_id = T2.publisher_id JOIN authors AS T1 ON T4.author_id = T1.author_id WHERE T1.full_name = 'Camille Dumas'"
    },
    {
      "question": "Combien d'éditeurs n'ont publié aucun livre ?",
      "sql": "SELECT COUNT(*) FROM publishers WHERE publisher_id NOT IN ( SELECT publisher_id FROM books )"
    },
    {
      "question": "Donnez les noms des éditeurs qui n'ont pas publié de livre après 2020.",
      "sql": "SELECT publisher_name FROM publishers EXCEPT SELECT T2.publisher_name FROM books AS T1 JOIN publishers AS T2 ON T1.publisher_id = T2.publisher_id WHERE T1.publication_year > 2020"
    },
    {
      "question": "Quel est le nom de l'auteur qui a écrit le plus de livres coûtant plus de 2 000 centimes ?",
      "sql": "SELECT T1.full_name FROM authors AS T1 JOIN books AS T2 ON T1.author_id = T2.author_id WHERE T2.price_cents > 2000 GROUP BY T1.author_id ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Trouvez les noms des éditeurs situés à Paris ou à Lyon.",
      "sql": "SELECT publisher_name FROM publishers WHERE city = 'Paris' UNION SELECT publisher_name FROM publishers WHERE city = 'Lyon'"
    },
    {
      "question": "Quels sont les identifiants des livres écrits par un auteur français ou algérien ?",
      "sql": "SELECT T1.book_id FROM books AS T1 JOIN authors AS T2 ON T1.author_id = T2.author_id WHERE T2.country = 'France' OR T2.country = 'Algeria'"
    },
    {
      "question": "Quel est le prix moyen des livres de la catégorie « Roman francophone » ?",
      "sql": "SELECT avg(T2.price_cents) FROM categories AS T1 JOIN books AS T2 ON T1.category_id = T2.category_id JOIN publishers AS T3 ON T2.publisher_id = T3.publisher_id WHERE T1.category_name = 'Roman francophone'"
    },
    {
      "question": "Quelle ville compte le plus grand nombre de clients ?",
      "sql": "SELECT city FROM customers GROUP BY city ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Retourne le titre du livre de « Camille Dumas » appartenant à la catégorie « Roman francophone » et coûtant le plus cher.",
      "sql": "SELECT T5.title FROM books AS T5 JOIN authors AS T2 ON T5.author_id = T2.author_id JOIN categories AS T1 ON T5.category_id = T1.category_id JOIN publishers AS T3 ON T5.publisher_id = T3.publisher_id WHERE T2.full_name = 'Camille Dumas' AND T1.category_name = 'Roman francophone' ORDER BY T5.price_cents DESC LIMIT 1"
    },
    {
      "question": "Donnez le titre et le prix du livre le plus cher.",
      "sql": "SELECT title, price_cents FROM books WHERE price_cents = (SELECT price_cents FROM books ORDER BY price_cents DESC LIMIT 1)"
    },
    {
      "question": "Quel est le nom de l'éditeur du livre le plus cher, avec son prix, son année de publication et son stock ?",
      "sql": "SELECT T2.publisher_name, T1.price_cents, T1.publication_year, T1.stock_count FROM books AS T1 JOIN publishers AS T2 ON T1.publisher_id = T2.publisher_id GROUP BY T1.book_id ORDER BY T1.price_cents DESC LIMIT 1"
    },
    {
      "question": "Trouvez le titre du livre écrit par l'auteur le plus jeune.",
      "sql": "SELECT T1.title FROM books AS T1 JOIN authors AS T2 ON T1.author_id = T2.author_id ORDER BY T2.birth_year DESC LIMIT 1"
    },
    {
      "question": "Quel pays compte le plus d'auteurs actifs ?",
      "sql": "SELECT country FROM authors WHERE active = 1 GROUP BY country ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quel est le nom de l'éditeur qui compte le moins de livres ?",
      "sql": "SELECT T2.publisher_name FROM books AS T1 JOIN publishers AS T2 ON T1.publisher_id = T2.publisher_id GROUP BY T1.publisher_id ORDER BY count(*) LIMIT 1"
    },
    {
      "question": "Quel éditeur a été fondé le plus récemment ?",
      "sql": "SELECT publisher_name FROM publishers WHERE founded_year = ( SELECT MAX ( founded_year ) FROM publishers )"
    },
    {
      "question": "Dans quelle ville se trouve l'éditeur du livre « Les Villes de Verre », et quel est son nom ?",
      "sql": "SELECT T2.city, T2.publisher_name FROM books AS T1 JOIN publishers AS T2 ON T1.publisher_id = T2.publisher_id JOIN categories AS T3 ON T1.category_id = T3.category_id WHERE T1.title = 'Les Villes de Verre' AND T3.category_name = 'Roman francophone'"
    }
  ]
}

{
  "examples": [
    {
      "question": "Comptez le nombre de livres qui n'ont jamais été commandés.",
      "sql": "SELECT count(*) FROM books WHERE book_id NOT IN ( SELECT book_id FROM order_lines )"
    },
    {
      "question": "Quel est l'identifiant de l'éditeur qui publie le moins de livres ?",
      "sql": "SELECT publisher_id FROM books GROUP BY publisher_id ORDER BY count(*) LIMIT 1"
    },
    {
      "question": "Quel auteur a le plus grand nombre de livres apparaissant dans les lignes de commande ? Indiquez son identifiant et son nom complet.",
      "sql": "SELECT T1.author_id, T1.full_name FROM authors AS T1 JOIN books AS T2 ON T1.author_id = T2.author_id JOIN order_lines AS T3 ON T2.book_id = T3.book_id GROUP BY T1.author_id ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quels sont les noms des clients qui ont acheté le livre « Les Villes de Verre » au moins une fois ?",
      "sql": "SELECT T1.full_name FROM customers AS T1 JOIN orders AS T2 ON T1.customer_id = T2.customer_id JOIN order_lines AS T3 ON T2.order_id = T3.order_id JOIN books AS T4 ON T3.book_id = T4.book_id WHERE T4.title = 'Les Villes de Verre' GROUP BY T1.customer_id HAVING count(*) >= 1"
    },
    {
      "question": "Combien de livres de catégorie adulte ont été écrits par des auteurs actifs ?",
      "sql": "SELECT count(*) FROM authors AS T1 JOIN books AS T2 ON T1.author_id = T2.author_id JOIN categories AS T3 ON T3.category_id = T2.category_id WHERE T3.age_group = 'adulte' AND T1.active = 1"
    },
    {
      "question": "Trouvez l'identifiant de tous les livres dont le prix est supérieur au prix moyen des livres.",
      "sql": "SELECT book_id FROM books WHERE price_cents > (SELECT AVG(price_cents) FROM books)"
    },
    {
      "question": "Trouvez les catégories qui ne sont associées à aucun livre.",
      "sql": "SELECT category_id FROM categories WHERE category_id NOT IN (SELECT category_id FROM books)"
    },
    {
      "question": "Chez quel éditeur et dans quelle catégorie sont publiés les livres de Camille Dumas ?",
      "sql": "SELECT DISTINCT T1.publisher_name, T4.category_name FROM categories AS T4 JOIN books AS T3 ON T4.category_id = T3.category_id JOIN authors AS T2 ON T2.author_id = T3.author_id JOIN publishers AS T1 ON T1.publisher_id = T3.publisher_id WHERE T2.full_name = 'Camille Dumas'"
    },
    {
      "question": "Trouvez l'identifiant de la catégorie qui contient le plus de livres.",
      "sql": "SELECT category_id FROM books GROUP BY category_id ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quel est le titre du livre publié à Paris par Camille Dumas ?",
      "sql": "SELECT T2.title FROM publishers AS T1 JOIN books AS T2 ON T1.publisher_id = T2.publisher_id JOIN authors AS T3 ON T2.author_id = T3.author_id WHERE T1.city = 'Paris' AND T3.full_name = 'Camille Dumas'"
    },
    {
      "question": "Quel est le titre du livre le plus cher de la catégorie « Roman francophone » ?",
      "sql": "SELECT title FROM books WHERE price_cents = ( SELECT MAX ( price_cents ) FROM books WHERE category_id = 1 ) AND category_id = 1"
    },
    {
      "question": "Combien de livres appartiennent à la catégorie « Roman francophone » ou à la catégorie « Policier » ?",
      "sql": "SELECT count(*) FROM books AS T1 JOIN categories AS T2 ON T1.category_id = T2.category_id WHERE T2.category_name = 'Roman francophone' OR T2.category_name = 'Policier'"
    },
    {
      "question": "Quels sont les identifiants des commandes qui contiennent le livre « Les Villes de Verre » ainsi qu'un autre livre ?",
      "sql": "SELECT DISTINCT T3.order_id FROM books AS T2 JOIN order_lines AS T3 ON T3.book_id = T2.book_id JOIN order_lines AS T4 ON T4.order_id = T3.order_id JOIN books AS T1 ON T1.book_id = T4.book_id WHERE T2.title = 'Les Villes de Verre' AND T1.book_id != T2.book_id"
    },
    {
      "question": "Quel éditeur publie les livres de Camille Dumas classés dans la catégorie « Roman francophone » ?",
      "sql": "SELECT T2.publisher_name FROM books AS T4 JOIN publishers AS T2 ON T4.publisher_id = T2.publisher_id JOIN categories AS T3 ON T4.category_id = T3.category_id JOIN authors AS T1 ON T4.author_id = T1.author_id WHERE T1.full_name = 'Camille Dumas' AND T3.category_name = 'Roman francophone'"
    },
    {
      "question": "Quels sont les noms complets, les années de naissance et les pays des auteurs originaires du même pays que Camille Dumas ?",
      "sql": "SELECT full_name, birth_year, country FROM authors WHERE country = (SELECT country FROM authors WHERE full_name = 'Camille Dumas')"
    },
    {
      "question": "Quels sont les 3 auteurs qui ont écrit le plus de livres ? Donnez leur nom complet et leur identifiant.",
      "sql": "SELECT T1.full_name, T1.author_id FROM authors AS T1 JOIN books AS T2 ON T1.author_id = T2.author_id GROUP BY T1.author_id ORDER BY count(*) DESC LIMIT 3"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quels sont les éditeurs de livres appartenant à la catégorie « Roman francophone » ?",
      "sql": "SELECT DISTINCT T1.publisher_name FROM publishers AS T1 JOIN books AS T2 ON T1.publisher_id = T2.publisher_id JOIN authors AS T3 ON T2.author_id = T3.author_id JOIN categories AS T4 ON T2.category_id = T4.category_id WHERE T4.category_name = 'Roman francophone'"
    },
    {
      "question": "Quelles sont les années de publication des livres écrits par un auteur français ou édités à Paris, dans les deux cas ?",
      "sql": "SELECT T1.publication_year FROM books AS T1 JOIN authors AS T2 ON T1.author_id = T2.author_id JOIN publishers AS T3 ON T1.publisher_id = T3.publisher_id WHERE T2.country = 'France' INTERSECT SELECT T1.publication_year FROM books AS T1 JOIN authors AS T2 ON T1.author_id = T2.author_id JOIN publishers AS T3 ON T1.publisher_id = T3.publisher_id WHERE T3.city = 'Paris'"
    },
    {
      "question": "Quels auteurs ont écrit des livres appartenant à la même catégorie qu'un livre de Camille Dumas ?",
      "sql": "SELECT T1.full_name FROM books AS T4 JOIN authors AS T1 ON T4.author_id = T1.author_id JOIN categories AS T5 ON T5.category_id = T4.category_id JOIN books AS T3 ON T5.category_id = T3.category_id JOIN authors AS T2 ON T3.author_id = T2.author_id WHERE T2.full_name = 'Camille Dumas'"
    },
    {
      "question": "Quels clients n'ont passé aucune commande ?",
      "sql": "SELECT full_name FROM customers EXCEPT SELECT T1.full_name FROM customers AS T1 JOIN orders AS T2 ON T1.customer_id = T2.customer_id"
    },
    {
      "question": "Pour chaque livre, indiquez sa catégorie et le nom de son auteur, en classant le résultat selon l'année de naissance croissante des auteurs.",
      "sql": "SELECT T3.category_name, T2.full_name FROM books AS T1 JOIN authors AS T2 ON T1.author_id = T2.author_id JOIN categories AS T3 ON T1.category_id = T3.category_id ORDER BY T2.birth_year ASC"
    },
    {
      "question": "Quels sont les titres des livres qui n'ont jamais été commandés ?",
      "sql": "SELECT title FROM books EXCEPT SELECT T1.title FROM books AS T1 JOIN order_lines AS T2 ON T1.book_id = T2.book_id"
    },
    {
      "question": "Donnez l'identifiant et le nom du client qui a passé le moins de commandes.",
      "sql": "SELECT T1.customer_id, T2.full_name FROM orders AS T1 JOIN customers AS T2 ON T1.customer_id = T2.customer_id GROUP BY T1.customer_id ORDER BY count(*) ASC LIMIT 1"
    },
    {
      "question": "Quel éditeur a été fondé le plus récemment ?",
      "sql": "SELECT publisher_name FROM publishers WHERE founded_year = (SELECT MAX ( founded_year ) FROM publishers)"
    },
    {
      "question": "Trouvez l'identifiant et le nom de l'auteur qui a publié le plus de livres.",
      "sql": "SELECT T1.author_id, T2.full_name FROM books AS T1 JOIN authors AS T2 ON T1.author_id = T2.author_id GROUP BY T1.author_id ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Chez quel éditeur la valeur totale des livres publiés est-elle la plus faible ? Indiquez l'éditeur et cette valeur totale.",
      "sql": "SELECT publishers.publisher_name, sum(books.price_cents) FROM books JOIN publishers ON books.publisher_id = publishers.publisher_id GROUP BY publishers.publisher_id ORDER BY sum(books.price_cents) ASC LIMIT 1"
    },
    {
      "question": "Quels sont les titres écrits par des auteurs français et publiés par un éditeur situé à Paris ?",
      "sql": "SELECT T1.title FROM books AS T1 JOIN publishers AS T2 ON T1.publisher_id = T2.publisher_id JOIN authors AS T3 ON T1.author_id = T3.author_id WHERE T2.city = 'Paris' AND T3.country = 'France'"
    },
    {
      "question": "En quelle année Camille Dumas a-t-elle publié le plus de livres ?",
      "sql": "SELECT COUNT ( DISTINCT T3.book_id ), T3.publication_year FROM authors AS T1 JOIN books AS T3 ON T1.author_id = T3.author_id JOIN categories AS T2 ON T3.category_id = T2.category_id WHERE T1.full_name LIKE 'Camille Dumas' GROUP BY T3.publication_year ORDER BY COUNT ( DISTINCT T3.book_id ) DESC"
    },
    {
      "question": "Retournez les titres des livres de Camille Dumas publiés par Les Editions du Canal, dans la catégorie « Roman francophone », et coûtant plus de 1800 centimes.",
      "sql": "SELECT T4.title FROM books AS T4 JOIN publishers AS T2 ON T4.publisher_id = T2.publisher_id JOIN authors AS T1 ON T4.author_id = T1.author_id JOIN categories AS T3 ON T4.category_id = T3.category_id WHERE T1.full_name = 'Camille Dumas' AND T2.publisher_name = 'Les Editions du Canal' AND T3.category_name = 'Roman francophone' AND T4.price_cents > 1800"
    },
    {
      "question": "Quelle ville compte le plus de clients ?",
      "sql": "SELECT city, COUNT(*) FROM customers WHERE loyalty_level != 'silver' GROUP BY city ORDER BY COUNT(*) DESC LIMIT 1"
    },
    {
      "question": "Quels livres de plus de 1800 centimes peut-on trouver chez un éditeur parisien, écrits par un auteur français ?",
      "sql": "SELECT T2.city, T1.title FROM books AS T1 JOIN publishers AS T2 ON T1.publisher_id = T2.publisher_id JOIN authors AS T3 ON T1.author_id = T3.author_id WHERE T2.city = 'Paris' AND T3.country = 'France' AND T1.price_cents > 1800"
    },
    {
      "question": "Quels auteurs ont écrit des livres commandés dans la même commande qu'un livre de Camille Dumas ?",
      "sql": "SELECT T2.full_name FROM orders AS T7 JOIN order_lines AS T5 ON T7.order_id = T5.order_id JOIN books AS T6 ON T6.book_id = T5.book_id JOIN authors AS T1 ON T6.author_id = T1.author_id JOIN order_lines AS T3 ON T7.order_id = T3.order_id JOIN books AS T4 ON T4.book_id = T3.book_id JOIN authors AS T2 ON T4.author_id = T2.author_id WHERE T1.full_name = 'Camille Dumas'"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quel animal est né le plus récemment ?",
      "sql": "SELECT name FROM animals WHERE birth_year = ( SELECT MAX ( birth_year ) FROM animals );"
    },
    {
      "question": "Quel mode de paiement est le moins utilisé ?",
      "sql": "SELECT payment_method FROM payments GROUP BY payment_method ORDER BY count(*) ASC LIMIT 1;"
    },
    {
      "question": "Donnez les villes des clients inscrits avant 2021 ou après 2022.",
      "sql": "SELECT city FROM clients WHERE joined_on < '2021-01-01' UNION SELECT city FROM clients WHERE joined_on > '2022-01-01';"
    },
    {
      "question": "Quel vétérinaire a été recruté le plus récemment parmi ceux qui ont déjà eu un rendez-vous ?",
      "sql": "SELECT full_name FROM veterinarians WHERE hired_on = ( SELECT MAX ( T1.hired_on ) FROM appointments AS T2 JOIN veterinarians AS T1 ON T2.veterinarian_id = T1.veterinarian_id );"
    },
    {
      "question": "Quel est le montant total des paiements et la durée totale des rendez-vous de moins d'une heure ?",
      "sql": "SELECT sum(T1.amount_eur), sum(T2.duration_minutes) FROM payments AS T1 JOIN appointments AS T2 ON T1.appointment_id = T2.appointment_id WHERE T2.duration_minutes < 60;"
    },
    {
      "question": "Quel animal est né le plus récemment parmi les chats ?",
      "sql": "SELECT name FROM animals WHERE birth_year = ( SELECT MAX ( birth_year ) FROM animals WHERE species = 'chat' ) AND species = 'chat';"
    },
    {
      "question": "Quels motifs de rendez-vous concernent des chats ?",
      "sql": "SELECT T2.reason FROM procedures AS T1 JOIN appointments AS T2 ON T1.appointment_id = T2.appointment_id JOIN animals AS T3 ON T2.animal_id = T3.animal_id WHERE T3.species = 'chat';"
    },
    {
      "question": "Dans quelle ville y a-t-il le moins de clients ?",
      "sql": "SELECT city FROM clients GROUP BY city ORDER BY count(*) LIMIT 1;"
    },
    {
      "question": "Affichez les espèces et le nombre d'animaux correspondants, par ordre décroissant.",
      "sql": "SELECT species, COUNT(*) FROM animals GROUP BY species ORDER BY COUNT(*) DESC;"
    },
    {
      "question": "Quels sont l'identifiant et le nom du vétérinaire ayant reçu le plus de rendez-vous ?",
      "sql": "SELECT T1.veterinarian_id, T2.full_name FROM appointments AS T1 JOIN veterinarians AS T2 ON T1.veterinarian_id = T2.veterinarian_id GROUP BY T1.veterinarian_id ORDER BY count(*) DESC LIMIT 1;"
    },
    {
      "question": "Quels actes de diagnostic ont été réalisés par des vétérinaires en dermatologie pour plus de 50 euros ?",
      "sql": "SELECT T1.procedure_name, T2.full_name FROM procedures AS T1 JOIN veterinarians AS T2 ON T1.performed_by = T2.veterinarian_id WHERE T2.specialty = 'dermatologie' AND T1.category = 'diagnostic' AND T1.amount_eur > 50;"
    },
    {
      "question": "Quel acte est le moins cher parmi ceux réalisés par les vétérinaires ayant reçu un animal pour boiterie ?",
      "sql": "SELECT procedure_name FROM procedures WHERE amount_eur = ( SELECT MIN ( amount_eur ) FROM procedures WHERE performed_by IN ( SELECT veterinarian_id FROM appointments WHERE reason = 'boiterie' ) ) AND performed_by IN ( SELECT veterinarian_id FROM appointments WHERE reason = 'boiterie' );"
    },
    {
      "question": "Quels clients ont eu un acte d'imagerie pour leur animal ?",
      "sql": "SELECT T1.full_name FROM clients AS T1 JOIN animals AS T2 ON T1.client_id = T2.client_id JOIN appointments AS T3 ON T2.animal_id = T3.animal_id JOIN procedures AS T4 ON T3.appointment_id = T4.appointment_id WHERE T4.category = 'imagerie';"
    },
    {
      "question": "Quel vétérinaire a suivi le plus grand nombre d'animaux différents ?",
      "sql": "SELECT veterinarian_id FROM appointments GROUP BY ( veterinarian_id ) ORDER BY COUNT ( DISTINCT animal_id ) DESC LIMIT 1;"
    },
    {
      "question": "Quel vétérinaire compte le plus grand nombre de rendez-vous associés à des paiements pour des actes de prévention ?",
      "sql": "SELECT T3.full_name FROM procedures AS T1 JOIN appointments AS T2 ON T1.appointment_id = T2.appointment_id JOIN veterinarians AS T3 ON T2.veterinarian_id = T3.veterinarian_id JOIN payments AS T4 ON T2.appointment_id = T4.appointment_id WHERE T1.category = 'prevention' GROUP BY T3.full_name ORDER BY COUNT ( DISTINCT T2.appointment_id ) DESC LIMIT 1;"
    },
    {
      "question": "Quels chiens ont eu un rendez-vous avec un vétérinaire en médecine générale ?",
      "sql": "SELECT T1.name FROM animals AS T1 JOIN appointments AS T2 ON T1.animal_id = T2.animal_id JOIN veterinarians AS T3 ON T2.veterinarian_id = T3.veterinarian_id WHERE T1.species = 'chien' AND T3.specialty = 'medecine_generale';"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quelle est la culture la plus fréquemment cultivée ?",
      "sql": "SELECT crop_name FROM cultivation GROUP BY crop_name ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quels sont les identifiants des cultures semées le 9 avril 2024 mais pas le 22 mars 2024 ?",
      "sql": "SELECT cultivation_id FROM cultivation WHERE sowing_date = '2024-04-09' EXCEPT SELECT cultivation_id FROM cultivation WHERE sowing_date = '2024-03-22'"
    },
    {
      "question": "Donnez le nom du producteur et le montant du versement correspondant au versement le plus faible.",
      "sql": "SELECT T1.full_name, T3.amount_eur FROM grower AS T1 JOIN intake AS T2 ON T1.grower_id = T2.grower_id JOIN payout AS T3 ON T2.intake_id = T3.intake_id ORDER BY T3.amount_eur LIMIT 1"
    },
    {
      "question": "Quels sont les identifiants des cultures récoltées qui ne sont associées à aucune réception de qualité B ?",
      "sql": "SELECT cultivation_id FROM cultivation WHERE status = 'recolte' AND cultivation_id NOT IN (SELECT cultivation_id FROM intake WHERE quality_grade = 'B')"
    },
    {
      "question": "Combien de parcelles ne sont associées à aucune réception de qualité B ?",
      "sql": "SELECT count(*) FROM parcel WHERE parcel_id NOT IN (SELECT DISTINCT cultivation_id FROM intake WHERE quality_grade = 'B')"
    },
    {
      "question": "Quelles cultures et quelles dates de semis sont associées aux versements de Claire Martin ?",
      "sql": "SELECT DISTINCT T4.crop_name, T4.sowing_date FROM payout AS T2 JOIN grower AS T1 ON T2.grower_id = T1.grower_id JOIN intake AS T3 ON T3.intake_id = T2.intake_id JOIN cultivation AS T4 ON T4.cultivation_id = T3.cultivation_id JOIN parcel AS T5 ON T5.parcel_id = T4.parcel_id WHERE T1.full_name = 'Claire Martin' ORDER BY T4.sowing_date DESC"
    },
    {
      "question": "Quels producteurs ont cultivé une parcelle ou possèdent une parcelle ? Donnez leurs identifiants.",
      "sql": "SELECT grower_id FROM cultivation UNION SELECT grower_id FROM parcel"
    },
    {
      "question": "Combien de cultures sont enregistrées dans chaque commune ?",
      "sql": "SELECT T3.commune, count(*) FROM cultivation AS T1 JOIN parcel AS T2 ON T1.parcel_id = T2.parcel_id JOIN grower AS T3 ON T1.grower_id = T3.grower_id GROUP BY T3.commune"
    },
    {
      "question": "Quels producteurs biologiques ont reçu moins de cinq livraisons ? Donnez leurs identifiants.",
      "sql": "SELECT DISTINCT T1.grower_id FROM grower AS T1 JOIN cultivation AS T2 ON T1.grower_id = T2.grower_id JOIN intake AS T3 ON T2.cultivation_id = T3.cultivation_id WHERE T1.organic_certified = 1 GROUP BY T1.grower_id HAVING COUNT ( DISTINCT T3.intake_id ) < 5"
    },
    {
      "question": "Quel est le nom de la culture la plus fréquente parmi les cultures des parcelles ?",
      "sql": "SELECT T2.crop_name FROM parcel AS T1 JOIN cultivation AS T2 ON T1.parcel_id = T2.parcel_id GROUP BY T2.crop_name ORDER BY COUNT(*) DESC LIMIT 1"
    },
    {
      "question": "Quel producteur reçoit en moyenne les montants les plus faibles ? Donnez son nom et son identifiant.",
      "sql": "SELECT T1.full_name, T1.grower_id FROM grower AS T1 JOIN payout AS T2 ON T1.grower_id = T2.grower_id GROUP BY T1.grower_id ORDER BY avg(T2.amount_eur) ASC LIMIT 1"
    },
    {
      "question": "Quel est le nom du producteur associé à la réception dont la quantité est la plus faible ?",
      "sql": "SELECT T1.full_name FROM grower AS T1 JOIN intake AS T2 ON T1.grower_id = T2.grower_id ORDER BY T2.quantity_kg LIMIT 1"
